--- cart.js ---
export function cartLabel(count) {
  if (count === 0) return 'Nothing in your cart yet';
  return `${count} item${count === 1 ? '' : 's'}`;
}
--- cart.test.js ---
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { cartLabel } from './cart.js';
test('empty cart label', () => assert.equal(cartLabel(0), 'Nothing in your cart yet'));
test('singular cart label', () => assert.equal(cartLabel(1), '1 item'));
test('plural cart label', () => assert.equal(cartLabel(2), '2 items'));
